const stable=v=>Array.isArray(v)?v.map(stable):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,stable(v[k])])):v;
const same=(a,b)=>JSON.stringify(stable(a))===JSON.stringify(stable(b));
const ids=new Set(Object.values(window.TRIGGLE_CLASSES).flatMap(g=>g.items.map(q=>q.id)));
chapter.textbookQuestionIds=chapter.textbookQuestionIds||[];
const pending=new Set();
for(const item of entries){const existing=grade.items.find(q=>q.id===item.id);if(pending.has(item.id)||(ids.has(item.id)&&(!existing||!same(existing,item))))throw Error('Duplicate bulk ID '+item.id);pending.add(item.id);}
for(const item of entries){if(!ids.has(item.id)){grade.items.push(item);ids.add(item.id);}if(!chapter.textbookQuestionIds.includes(item.id))chapter.textbookQuestionIds.push(item.id);}
